    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    occupied = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value != bg]
